 * Transcript parsing utilities for Claude Code JSONL files.
 *
 * Entries are emitted in chronological order, so span creation walks them
 * sequentially. These helpers cover reading the file, normalizing timestamps
 * to nanoseconds, flattening message content to text, and locating the
 * "real" user messages (as opposed to tool results, compact summaries, and
 * skill-injection framing).
 */

import { readFileSync } from 'node:fs';
import type { ContentBlock, TranscriptEntry } from './types.js';

export const NANOSECONDS_PER_SECOND = 1e9;
export const NANOSECONDS_PER_MS = 1e6;

/** Read and parse a Claude Code JSONL transcript file, one entry per line. */
export function readTranscript(filePath: string): TranscriptEntry[] {
  const content = readFileSync(filePath, 'utf-8');
  return content
    .split('\n')
    .filter((line) => line.trim())
    .map((line) => JSON.parse(line) as TranscriptEntry);
}

/**
 * Convert a timestamp to nanoseconds since the Unix epoch.
 *
 * ISO date strings are parsed via `Date` and scaled from milliseconds.
 * Numeric values are interpreted by magnitude: `>= 1e13` are already
 * nanoseconds, `>= 1e10` are milliseconds, and anything smaller is treated
 * as Unix seconds. Returns null for null/undefined/empty-string inputs and
 * for strings that are not valid dates.
 */
export function parseTimestampToNs(ts: string | number | null | undefined): number | null {
  if (ts === null || ts === undefined || ts === '') {
    return null;
  }

  if (typeof ts === 'number') {
    if (!Number.isFinite(ts)) {
      return null;
    }
    if (ts >= 1e13) {
      return Math.floor(ts);
    }
    if (ts >= 1e10) {
      return Math.floor(ts * NANOSECONDS_PER_MS);
    }
    return Math.floor(ts * NANOSECONDS_PER_SECOND);
  }

  const ms = new Date(ts).getTime();
  if (Number.isNaN(ms)) {
    return null;
  }
  return Math.floor(ms * NANOSECONDS_PER_MS);
}

/**
 * Flatten a message's `content` to plain text. Strings are returned as-is;
 * arrays are reduced to the `text` fields of their `text` blocks joined by
 * newlines. An empty array (or a value with no text blocks) yields ''.
 */
export function extractTextContent(
  content: string | Array<{ type: string; text?: string; [key: string]: unknown }>,
): string {
  if (typeof content === 'string') {
    return content;
  }
  if (!Array.isArray(content)) {
    return '';
  }
  return content
    .filter((block) => block.type === 'text')
    .map((block) => block.text ?? '')
    .join('\n');
}

/**
 * Return true if `entry` is a "real" user message — a genuine human turn, as
 * opposed to a tool-result carrier, a compact summary, or a skill-injection
 * message.
 *
 * Skipped shapes:
 *   - non-user entries
 *   - user entries whose content is an array of `tool_result` blocks
 *   - entries with `isCompactSummary: true`
 *   - user text starting with 'Base directory:' (skill injection framing)
 */
export function isRealUserMessage(entry: TranscriptEntry): boolean {
  if (entry.type !== 'user') {
    return false;
  }
  if (entry.isCompactSummary === true) {
    return false;
  }

  const content = entry.message?.content;
  if (
    Array.isArray(content) &&
    content.length > 0 &&
    content.every((block) => (block as ContentBlock).type === 'tool_result')
  ) {
    return false;
  }

  const text = extractTextContent(content ?? '');
  if (text.startsWith('Base directory:')) {
    return false;
  }

  return true;
}

/**
 * Find the index of the last real user message in the transcript, or null if
 * there is none (including for an empty transcript).
 */
export function findLastUserMessageIndex(entries: TranscriptEntry[]): number | null {
  for (let i = entries.length - 1; i >= 0; i--) {
    if (isRealUserMessage(entries[i])) {
      return i;
    }
  }
  return null;
}

/**
 * Find the index of the first real user message in the transcript, or null if
 * there is none.
 */
export function findFirstUserMessageIndex(entries: TranscriptEntry[]): number | null {
  for (let i = 0; i < entries.length; i++) {
    if (isRealUserMessage(entries[i])) {
      return i;
    }
  }
  return null;
}

/**
 * Search from `startIndex` onward for the last assistant entry that has text
 * content, returning its extracted text. Returns null if no assistant entry
 * in that range has text.
 */
export function findFinalAssistantResponse(
  entries: TranscriptEntry[],
  startIndex: number,
): string | null {
  let result: string | null = null;
  for (let i = Math.max(0, startIndex); i < entries.length; i++) {
    const entry = entries[i];
    if (entry.type === 'assistant' && entry.message) {
      const text = extractTextContent(entry.message.content);
      if (text.trim()) {
        result = text;
      }
    }
  }
  return result;
}
